const roles = [
  { name: "architect", provider: "magpie", model: "codex/gpt-6.1-sol" },
  { name: "implementer", provider: "magpie", model: "auto/deepseek-v4.1-flash" },
  { name: "reviewer", provider: "magpie", model: "auto/glm-5.3-flash" },
  { name: "validator", provider: "magpie", model: "auto/qwen3.8-flash" },
];

const spawn = {};
for (const r of roles) {
  try {
    const res = await tools.spawn_teammate({
      name: r.name,
      description: `Role table verification probe for ${r.name}`,
      prompt: "Reply READY",
      context: "fresh",
      agent_options: { provider: r.provider, model: r.model },
    });
    spawn[r.name] = res;
  } catch (e) {
    spawn[r.name] = { error: String(e && e.message) };
  }
}

const agents = await tools.list_agents({});
console.log(JSON.stringify({ spawn, agents }, null, 2));
return { spawn, agents };
